/// <summary>
/// PaffH 12.08.25
/// </summary>
/// <returns>QueryBuildRange</returns>
public static Query queryLookupContactPersonById()
{
    Query query = new Query();
    query.allowCrossCompany(true);
    query.addCompanyRange(curExt());
    query.addDataSource(tableNum(ContactPerson));
    return query;
}

/// <summary>
/// PaffH 21.08.25
/// </summary>
/// <param name = "_q">Query</param>
/// <param name = "_dataAreaId">DataAreaId</param>
public static void setDataAreaId(Query _q, DataAreaId _dataAreaId = curExt())
{
    if (_dataAreaId)
    {
        _q.clearCompanyRange();
        _q.addCompanyRange(_dataAreaId);
    }
}

/// <summary>
/// PaffH 12.08.25
/// last modified: PaffH 19.11.25
/// get contactperson from query
/// </summary>
/// <param name = "_q">Query</param>
/// <param name = "_newQueryValue">str</param>
/// <returns>ContactPerson</returns>
public static ContactPerson queryRunLookupContactPersonById(Query _q, str _newQueryValue = '')
{
    ContactPerson contactPerson;
    if (!prmIsDefault(_newQueryValue))
    {
        NDXContactPersonLookupClass::queryBuildRangeLookupContactPersonById(_q, _newQueryValue);
    }
    QueryRun qr = new QueryRun(_q);
    if (qr.next())
    {
        contactPerson = qr.get(tableNum(ContactPerson));
    }
    return contactPerson;
}

/// <summary>
/// PaffH 12.08.25
/// create range for lookup contactperson
/// </summary>
/// <param name = "_query">Query (build with: queryLookupContactPerson())</param>
/// <param name = "_lookupValue">_lookupValue = ''</param>
/// <returns>QueryBuildRange</returns>
public static QueryBuildRange queryBuildRangeLookupContactPersonById(Query _query, str _lookupValue = '')
{
    QueryBuildDataSource qbdsContactPerson = _query.dataSourceTable(tableNum(ContactPerson));
    if (!qbdsContactPerson)
    {
        throw error("@SYS104799");
    }
    QueryBuildRange range = SysQuery::findOrCreateRange(qbdsContactPerson, fieldNum(ContactPerson, ContactPersonId));
    if (!prmIsDefault(_lookupValue))
    {
        range.value(queryValue(_lookupValue));
    }
    return range;
}

/// <summary>
