public static Query queryLookupContactPersonByName()
{
    Query query = new Query();
    QueryBuildDataSource qbdsDirPartyTable = query.addDataSource(tableNum(DirPartyTable));
    QueryBuildDataSource qbdsContactPerson = qbdsDirPartyTable.addDataSource(tableNum(ContactPerson));
    qbdsContactPerson.relations(true);
    qbdsContactPerson.fetchMode(QueryFetchMode::One2One);
    return query;
