/// <summary>
/// PaffH 12.08.25
/// </summary>
/// <returns>QueryBuildRange</returns>
public static Query queryLookupContactPersonByEmail()
{
    Query query = new Query();
    QueryBuildDataSource qbdsLogisticsElectronicAddress = query.addDataSource(tableNum(LogisticsElectronicAddress));
    QueryBuildDataSource qbdsDirPerson = qbdsLogisticsElectronicAddress.addDataSource(tableNum(DirPerson));
    qbdsDirPerson.clearLinks();
    qbdsDirPerson.addLink(fieldNum(LogisticsElectronicAddress, RecId), fieldNum(DirPerson, PrimaryContactEmail));
    qbdsDirPerson.fetchMode(QueryFetchMode::One2One);
    QueryBuildDataSource qbdsContactPerson = qbdsDirPerson.addDataSource(tableNum(ContactPerson));
    qbdsContactPerson.clearLinks();
    qbdsContactPerson.addLink(fieldNum(DirPerson, RecId), fieldNum(ContactPerson, Party));
    qbdsContactPerson.fetchMode(QueryFetchMode::One2One);
    return query;
    //select firstonly logisticsElectronicAddressLocal
    //                join dirPersonLocal
    //                join contactPersonLocal
    //                where logisticsElectronicAddressLocal.RecId == dirPersonLocal.PrimaryContactEmail &&
    //                dirPersonLocal.RecId == contactPersonLocal.Party &&
    //                logisticsElectronicAddressLocal.Locator == lookUpValue;
}

